// node tests/browser.mjs <playwright directory> <HTML> <evidence directory>
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import {pathToFileURL} from 'node:url';
const [playwright, html, evidence] = process.argv.slice(2);
const {chromium} = await import(pathToFileURL(path.resolve(playwright, 'index.mjs')));
await fs.mkdir(evidence, {recursive: true});
const browser = await chromium.launch({headless: true, args: ['--no-sandbox']});
try {
  const page = await browser.newPage({viewport: {width: 1600, height: 1200}});
  const errors = [], requests = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('request', r => requests.push(r.url()));
  await page.goto(pathToFileURL(path.resolve(html)).href);
  await page.waitForFunction(() => window.flowTest);
  const initial = await page.evaluate(() => flowTest.getState());
  assert(await page.locator('.slots').count() > 0);
  assert(await page.locator('.queue-node').count() > 0);
  assert(await page.locator('.queue-node .slot').evaluateAll(slots=>slots.every(s=>s.textContent==='' && s.getBoundingClientRect().width===24 && s.getBoundingClientRect().height===24)));
  assert(await page.locator('.slots').evaluateAll(rows=>rows.every(row=>[...row.children].every((s,i)=>!i||Math.abs(s.getBoundingClientRect().left-row.children[i-1].getBoundingClientRect().right)<.1))));
  await page.locator('.queue-node .slot').first().click();
  assert.match(await page.locator('#detail').innerText(), /FIFO position 0/);
  assert.equal(await page.locator('.slot.selected').count(),1);
  await page.locator('#next').click();
  assert.equal(await page.locator('.slot.selected').count(),1);
  await page.locator('#back').click();
  const qheading=page.locator('.queue-node h2').first();
  const qb=await qheading.boundingBox();
  await page.mouse.move(qb.x+5,qb.y+5);await page.mouse.down();await page.mouse.move(qb.x+20,qb.y+10);await page.mouse.up();
  assert.match(await qheading.locator('..').getAttribute('style'), /translate/);
  assert(await page.locator('.table-node table').count() > 0);
  assert.equal(await page.locator('.register-value').count(),4);
  await page.locator('.register-value').first().click();
  assert.match(await page.locator('#detail').innerText(),/value/);
  await page.locator('#next').click();
  assert.equal(await page.evaluate(() => flowTest.getPosition()), 1);
  await page.locator('#back').click();
  assert.deepEqual(await page.evaluate(() => flowTest.getState()), initial);
  const target = await page.evaluate(() => {
    const n=flowTest.events.findIndex(es => es.some(e => e.action==='state_write'));
    flowTest.goto(n+1);return n+1;
  });
  assert(await page.locator('.register-value.write-active').count() > 0);
  await page.locator('.table-node tr[data-index="0"]').last().click();
  assert.match(await page.locator('#detail').innerText(), /generation/);
  await page.screenshot({path:path.join(evidence,'allocated.png'),fullPage:true});
  await page.evaluate(() => flowTest.goto(flowTest.recording.commits.length));
  const final=await page.evaluate(() => flowTest.getState());
  const expected=await page.evaluate(() => {
    const s=structuredClone(flowTest.recording.initial);
    for(const c of flowTest.recording.commits)for(const [id,v]of Object.entries(c.changes))s[id]=v.after;
    return s;
  });
  assert.deepEqual(final,expected);
  await page.locator('#back').click();
  await page.locator('#next').click();
  assert.deepEqual(await page.evaluate(() => flowTest.getState()),final);
  await page.evaluate(n => flowTest.goto(n-1), target);
  await page.locator('#speed').selectOption('1600');
  const before=await page.evaluate(() => flowTest.getState());
  await page.locator('#play').click();
  await page.waitForFunction(() => document.querySelector('#phase').textContent.includes('①'));
  assert.deepEqual(await page.evaluate(() => flowTest.getState()),before);
  await page.screenshot({path:path.join(evidence,'read-phase.png'),fullPage:true});
  await page.locator('#play').click();
  const paused=await page.evaluate(() => flowTest.getPosition());
  await page.waitForTimeout(600);
  assert.equal(await page.evaluate(() => flowTest.getPosition()),paused);
  const heading=page.locator('.table-node h2').last();
  const box=await heading.boundingBox();
  await page.mouse.move(box.x+10,box.y+5);await page.mouse.down();await page.mouse.move(box.x+35,box.y+15);await page.mouse.up();
  assert.match(await heading.locator('..').getAttribute('style'), /translate/);
  await page.locator('#zoomout').click();
  assert.deepEqual(errors, []);
  assert(requests.every(url=>url.startsWith('file:')));
  await page.goto(pathToFileURL(path.resolve(path.dirname(html),'queue-latency.html')).href);
  await page.waitForFunction(()=>window.flowTest);
  assert.equal(await page.locator('.queue-node .slot').count(),4);
  await page.evaluate(()=>{for(let i=0;i<flowTest.recording.commits.length;i++){flowTest.goto(i+1);if(document.querySelector('.slot.delayed'))return;}throw Error('No waiting entry');});
  await page.locator('.slot.delayed').first().click();
  assert.match(await page.locator('#detail').innerText(),/ready_time/);
  await page.screenshot({path:path.join(evidence,'latency.png'),fullPage:true});
  await page.evaluate(()=>flowTest.goto(flowTest.recording.commits.length));
  assert.equal(await page.locator('.slot.selected').count(),1);
  assert.match(await page.locator('#detail').innerText(),/ready/);
  await page.evaluate(()=>flowTest.goto(0));
  assert.match(await page.locator('#detail').innerText(),/empty/);
  assert.deepEqual(errors,[]);
  console.log(JSON.stringify({barriers:expected?await page.locator('#seek').getAttribute('max'):0,objects:Object.keys(initial).length,errors,offline:true}));
} finally {await browser.close();}
